import{_ as i,o as a,c as t,a0 as e}from"./chunks/framework.DzvPB4Y-.js";const c=JSON.parse('{"title":"多箱型、库存与成本：箱数最少不一定最便宜","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/bpp1d/business-scenario.md","filePath":"zh-cn/frameworks/bpp1d/business-scenario.md"}'),l={name:"zh-cn/frameworks/bpp1d/business-scenario.md"};function n(h,s,p,r,k,d){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="多箱型、库存与成本-箱数最少不一定最便宜" tabindex="-1">多箱型、库存与成本：箱数最少不一定最便宜 <a class="header-anchor" href="#多箱型、库存与成本-箱数最少不一定最便宜" aria-label="Permalink to &quot;多箱型、库存与成本：箱数最少不一定最便宜&quot;">​</a></h1><p>完成<a href="./first-packing.html">第一次一维装箱</a>后，把同一批物品交给两种容器，练习把业务目标和库存传入模型。本页是两种语言可共用的<strong>新练习输入</strong>，用于替换第一课的输入。</p><h2 id="_1-先准备能手算的输入" tabindex="-1">1. 先准备能手算的输入 <a class="header-anchor" href="#_1-先准备能手算的输入" aria-label="Permalink to &quot;1. 先准备能手算的输入&quot;">​</a></h2><p>物品表：</p><div class="language-csv vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes material-theme-darker material-theme-lighter vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">id,</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">length,</span><span style="--shiki-dark:#82AAFF;--shiki-light:#6182B8;">weight,</span><span style="--shiki-dark:#545454;--shiki-dark-font-style:italic;--shiki-light:#90A4AE;--shiki-light-font-style:italic;">amount</span></span>
<span class="line"><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">a,</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">6,</span><span style="--shiki-dark:#82AAFF;--shiki-light:#6182B8;">1,</span><span style="--shiki-dark:#545454;--shiki-dark-font-style:italic;--shiki-light:#90A4AE;--shiki-light-font-style:italic;">2</span></span>
<span class="line"><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">b,</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">4,</span><span style="--shiki-dark:#82AAFF;--shiki-light:#6182B8;">1,</span><span style="--shiki-dark:#545454;--shiki-dark-font-style:italic;--shiki-light:#90A4AE;--shiki-light-font-style:italic;">2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>容器表：</p><div class="language-csv vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes material-theme-darker material-theme-lighter vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">id,</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">length,</span><span style="--shiki-dark:#82AAFF;--shiki-light:#6182B8;">max_weight,</span><span style="--shiki-dark:#545454;--shiki-dark-font-style:italic;--shiki-light:#90A4AE;--shiki-light-font-style:italic;">cost,</span><span style="--shiki-dark:#C3E88D;--shiki-light:#91B859;">inventory</span></span>
<span class="line"><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">small,</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">10,</span><span style="--shiki-dark:#82AAFF;--shiki-light:#6182B8;">100,</span><span style="--shiki-dark:#545454;--shiki-dark-font-style:italic;--shiki-light:#90A4AE;--shiki-light-font-style:italic;">3,</span><span style="--shiki-dark:#C3E88D;--shiki-light:#91B859;">2</span></span>
<span class="line"><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">large,</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">20,</span><span style="--shiki-dark:#82AAFF;--shiki-light:#6182B8;">100,</span><span style="--shiki-dark:#545454;--shiki-dark-font-style:italic;--shiki-light:#90A4AE;--shiki-light-font-style:italic;">10,</span><span style="--shiki-dark:#C3E88D;--shiki-light:#91B859;">1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>显式声明长度单位为 m、重量单位为 kg，间距先为零。净长度为 20 m；一个 large 或两个 small 都能装完，且不超重。</p><table tabindex="0"><thead><tr><th>目标</th><th>一个可验收的最优选择</th><th style="text-align:right;">箱数</th><th style="text-align:right;">总费用</th></tr></thead><tbody><tr><td>最少箱数</td><td>1 个 large</td><td style="text-align:right;">1</td><td style="text-align:right;">10</td></tr><tr><td>最小费用</td><td>2 个 small，各装 a+b</td><td style="text-align:right;">2</td><td style="text-align:right;">6</td></tr><tr><td>最少消耗长度</td><td>两种方案均为 20 m</td><td style="text-align:right;">不唯一</td><td style="text-align:right;">不由此目标决定</td></tr></tbody></table><p>这些是完整微型问题的手算结论。若生成预算截断导致程序没看到某种组合，必须保留受限候选模型的结论范围。</p><h2 id="_2-映射到真实入口" tabindex="-1">2. 映射到真实入口 <a class="header-anchor" href="#_2-映射到真实入口" aria-label="Permalink to &quot;2. 映射到真实入口&quot;">​</a></h2><p>Kotlin 使用 <code>Bpp1dCsvDatasetLoader</code>，Rust 使用 <code>load_packing_csv</code>；二者均需显式配置单位与数值解析，CSV 本身不带单位。也可按第一课的工厂直接构造 <code>Item</code>、<code>BinType</code> 和 <code>PackingProblem</code>。</p><p>以下只展示<strong>已经构造好 <code>problem</code> 之后</strong>的目标切换，不是独立程序：</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-p2mZv" id="tab-1nMFKUu" checked><label data-title="Kotlin" for="tab-1nMFKUu">Kotlin</label><input type="radio" name="group-p2mZv" id="tab-hUNZrcl"><label data-title="Rust" for="tab-hUNZrcl">Rust</label></div><div class="blocks"><div class="language-kotlin vp-adaptive-theme active line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes material-theme-darker material-theme-lighter vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">val</span><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;"> costProblem </span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">=</span><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;"> problem.</span><span style="--shiki-dark:#82AAFF;--shiki-light:#6182B8;">copy</span><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">(</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">object</span><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">ive </span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">=</span><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;"> PackingObjective.Cost)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes material-theme-darker material-theme-lighter vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#C792EA;--shiki-light:#9C3EDA;">let</span><span style="--shiki-dark:#C792EA;--shiki-light:#9C3EDA;"> mut</span><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;"> cost_problem </span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">=</span><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;"> problem</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">.</span><span style="--shiki-dark:#82AAFF;--shiki-light:#6182B8;">clone</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">();</span></span>
<span class="line"><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">cost_problem</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">.</span><span style="--shiki-dark:#EEFFFF;--shiki-light:#90A4AE;">objective </span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">=</span><span style="--shiki-dark:#FFCB6B;--shiki-light:#E2931D;"> PackingObjective</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">::</span><span style="--shiki-dark:#FFCB6B;--shiki-light:#E2931D;">Cost</span><span style="--shiki-dark:#89DDFF;--shiki-light:#39ADB5;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></div></div><p>枚举定义见 <a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp1d/bpp1d-domain-item-context/src/main/fuookami/ospf/kotlin/framework/bpp1d/domain/item/model/PackingProblem.kt" target="_blank" rel="noreferrer">Kotlin 输入模型</a>和 <a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp1d/src/domain/model.rs" target="_blank" rel="noreferrer">Rust 输入模型</a>。沿用第一课已接通的 solver 与结果处理，不要用换目标来替代后端接线。</p><h2 id="_3-一次只改一个条件" tabindex="-1">3. 一次只改一个条件 <a class="header-anchor" href="#_3-一次只改一个条件" aria-label="Permalink to &quot;3. 一次只改一个条件&quot;">​</a></h2><ol><li>将 small 库存从 2 改为 1，保持零间距。最小费用变为 10，使用一个 large；不允许悄悄再采购一个 small。</li><li>恢复 small 库存为 2，再把 large 库存改为零。仍可用两个 small，费用为 6。</li><li>在第 2 步基础上把 small 库存改为 1。总容量不足，应无可行完整方案。</li><li>恢复原始库存，只将间距改为 1 m。一个 large 装不下四件，small 也不能装 a+b；可用 large 装 a+a+b、small 装 b，费用为 13。验证这个新问题，而不是沿用旧断言。</li></ol><p>库存空值表示不限，零表示不能使用。业务适配器不能把两者转换成相同默认值。</p><h2 id="_4-交付前重算四个量" tabindex="-1">4. 交付前重算四个量 <a class="header-anchor" href="#_4-交付前重算四个量" aria-label="Permalink to &quot;4. 交付前重算四个量&quot;">​</a></h2><p>按实际放置统计 a、b 都恰好 2 件；按箱型统计库存；逐箱检查长度、承重和相邻间距；最后用实际使用箱数重算费用。即使消耗长度相同，费用和箱数也可能不同。</p><p>追加业务规则时，单组合禁配用 <code>PatternPolicy</code>；跨箱数量/预算规则考察 <code>PatternModelingExtension</code>，并检查 MILP、LP、final 与最终复核是否一致。不要只在报表里过滤掉违规箱子。</p><p>在第一课示例中直接替换物品与容器列表，保留单位、库存和目标字段；重新调用框架并独立重算结果。</p><p>完成后按<a href="./../integration.html">接入指南</a>把同一组数据、结果不变量与失败用例迁入自己的应用。</p><p>源码回归命令统一放在<a href="./../verification.html">仓库验证参考</a>；先完成业务输入、调用与结果复核，再按需验证。</p>`,24)])])}const g=i(l,[["render",n]]);export{c as __pageData,g as default};
